"""In-memory storage for books."""
from typing import Any

from app.models import Book


class Store:
    """Repository implementation for books with soft-delete support."""

    def __init__(self):
        self._items: dict[int, Book] = {}
        self._next: int = 1
        self._deleted: set[int] = set()

    # --- Repository protocol ---

    def insert(self, obj: Any) -> int:
        """Stores obj, assigns and returns a new id (ids start at 1)."""
        item = Book(id=self._next, name=obj)
        self._items[item.id] = item
        self._next += 1
        return item.id

    def fetch(self, obj_id: int) -> Any | None:
        """None if missing OR soft-deleted."""
        item = self._items.get(obj_id)
        if item is None or obj_id in self._deleted:
            return None
        return item

    def fetch_all(self) -> list:
        """Live (not deleted) objects, ascending id."""
        return sorted(
            [v for v in self._items.values() if v.id not in self._deleted],
            key=lambda x: x.id,
        )

    def mark_deleted(self, obj_id: int) -> bool:
        """Soft delete; False if missing or already deleted."""
        if obj_id in self._deleted or obj_id not in self._items:
            return False
        self._deleted.add(obj_id)
        return True

    # --- Legacy API (kept for backward compat) ---

    def add(self, name: str) -> Book:
        item = Book(id=self._next, name=name)
        self._items[item.id] = item
        self._next += 1
        return item

    def get(self, item_id: int) -> Book | None:
        return self._items.get(item_id)

    def all(self) -> list[Book]:
        return list(self._items.values())

    def clear_all(self) -> None:
        """Reset store: remove all items and reset id counter."""
        self._items.clear()
        self._deleted.clear()
        self._next = 1

