from dataclasses import asdict
from app.service import Service
from app import audit

svc = Service()


def reset():
    global svc
    svc = Service()
    audit.clear()


def create(payload: dict) -> dict:
    item = svc.create(payload["name"])
    audit.log_event("create", item.id)
    return asdict(item)


def get(item_id: int) -> dict:
    item = svc.get(item_id)
    if item is None:
        return {"error": "not_found"}
    return asdict(item)


def list_all() -> dict:
    return {"items": [asdict(x) for x in svc.list()]}


def delete(item_id: int) -> dict:
    ok = svc.delete(item_id)
    if ok:
        audit.log_event("delete", item_id)
        return {"ok": True}
    return {"error": "not_found"}


def page(cursor=None, size=2) -> dict:
    items = svc.list()
    if cursor is not None:
        items = [x for x in items if x.id > cursor]
    page_items = items[:size]
    if len(items) > size:
        next_id = page_items[-1].id
    else:
        next_id = None
    return {
        "items": [asdict(x) for x in page_items],
        "next": next_id,
    }


def history() -> dict:
    return {"events": audit.get_events()}

